   \\\"value\\\": \\\"custom\\\"\\n        }\\n      ]\\n    },\\n    {\\n      \\\"name\\\": \\\"titleBackgroundColor\\\",\\n      \\\"type\\\": \\\"color\\\",\\n      \\\"value\\\": \\\"#ffffff\\\",\\n      \\\"required\\\": true,\\n      \\\"label\\\": \\\"Title background\\\",\\n      \\\"showIf\\\": [\\n        {\\n          \\\"field\\\": \\\"theme\\\",\\n          \\\"operator\\\": \\\"eq\\\",\\n          \\\"value\\\": \\\"custom\\\"\\n        }\\n      ]\\n    },\\n    {\\n      \\\"name\\\": \\\"weekdayFont\\\",\\n      \\\"type\\\": \\\"font\\\",\\n      \\\"required\\\": false,\\n      \\\"label\\\": \\\"Weekday font (used for weekday row)\\\",\\n      \\\"showIf\\\": [\\n        {\\n          \\\"field\\\": \\\"theme\\\",\\n          \\\"operator\\\": \\\"eq\\\",\\n          \\\"value\\\": \\\"custom\\\"\\n        }\\n      ]\\n    },\\n    {\\n      \\\"name\\\": \\\"weekdayFontSize\\\",\\n      \\\"type\\\": \\\"float\\\",\\n      \\\"value\\\": \\\"16\\\",\\n      \\\"required\\\": true,\\n      \\\"label\\\": \\\"Weekday row font size\\\",\\n      \\\"showIf\\\": [\\n        {\\n          \\\"field\\\": \\\"theme\\\",\\n          \\\"operator\\\": \\\"eq\\\",\\n          \\\"value\\\": \\\"custom\\\"\\n        }\\n      ]\\n    },\\n    {\\n      \\\"name\\\": \\\"weekdayTextColor\\\",\\n      \\\"type\\\": \\\"color\\\",\\n      \\\"value\\\": \\\"#000000\\\",\\n      \\\"required\\\": true,\\n      \\\"label\\\": \\\"Weekday text color\\\",\\n      \\\"showIf\\\": [\\n        {\\n          \\\"field\\\": \\\"theme\\\",\\n          \\\"operator\\\": \\\"eq\\\",\\n          \\\"value\\\": \\\"custom\\\"\\n        }\\n      ]\\n    },\\n    {\\n      \\\"name\\\": \\\"weekdayBackgroundColor\\\",\\n      \\\"type\\\": \\\"color\\\",\\n      \\\"value\\\": \\\"#ffffff\\\",\\n      \\\"required\\\": true,\\n      \\\"label\\\": \\\"Weekday background\\\",\\n      \\\"showIf\\\": [\\n        {\\n          \\\"field\\\": \\\"theme\\\",\\n          \\\"operator\\\": \\\"eq\\\",\\n          \\\"value\\\": \\\"custom\\\"\\n        }\\n      ]\\n    },\\n    {\\n      \\\"name\\\": \\\"dateFont\\\",\\n      \\\"type\\\": \\\"font\\\",\\n      \\\"required\\\": false,\\n      \\\"label\\\": \\\"Date number font\\\",\\n      \\\"showIf\\\": [\\n        {\\n          \\\"field\\\": \\\"theme\\\",\\n          \\\"operator\\\": \\\"eq\\\",\\n          \\\"value\\\": \\\"custom\\\"\\n        }\\n      ]\\n    },\\n    {\\n      \\\"name\\\": \\\"dateFontSize\\\",\\n      \\\"type\\\": \\\"float\\\",\\n      \\\"value\\\": \\\"18\\\",\\n      \\\"required\\\": true,\\n      \\\"label\\\": \\\"Date number font size\\\",\\n      \\\"showIf\\\": [\\n        {\\n          \\\"field\\\": \\\"theme\\\",\\n          \\\"operator\\\": \\\"eq\\\",\\n          \\\"value\\\": \\\"custom\\\"\\n        }\\n      ]\\n    },\\n    {\\n      \\\"name\\\": \\\"eventTitleFont\\\",\\n      \\\"type\\\": \\\"font\\\",\\n      \\\"required\\\": false,\\n      \\\"label\\\": \\\"Event title font\\\",\\n      \\\"value\\\": \\\"Ubuntu-Medium.ttf\\\",\\n      \\\"showIf\\\": [\\n        {\\n          \\\"field\\\": \\\"theme\\\",\\n          \\\"operator\\\": \\\"eq\\\",\\n          \\\"value\\\": \\\"custom\\\"\\n        }\\n      ]\\n    },\\n    {\\n      \\\"name\\\": \\\"eventTimeFont\\\",\\n      \\\"type\\\": \\\"font\\\",\\n      \\\"required\\\": false,\\n      \\\"label\\\": \\\"Event time font\\\",\\n      \\\"value\\\": \\\"Ubuntu-Light.ttf\\\",\\n      \\\"showIf\\\": [\\n        {\\n          \\\"field\\\": \\\"theme\\\",\\n          \\\"operator\\\": \\\"eq\\\",\\n          \\\"value\\\": \\\"custom\\\"\\n        }\\n      ]\\n    },\\n    {\\n      \\\"name\\\": \\\"eventFontSize\\\",\\n      \\\"type\\\": \\\"float\\\",\\n      \\\"value\\\": \\\"14\\\",\\n      \\\"required\\\": true,\\n      \\\"label\\\": \\\"Event font size\\\",\\n      \\\"showIf\\\": [\\n        {\\n          \\\"field\\\": \\\"theme\\\",\\n          \\\"operator\\\": \\\"eq\\\",\\n          \\\"value\\\": \\\"custom\\\"\\n        }\\n      ]\\n    },\\n    {\\n      \\\"name\\\": \\\"padding\\\",\\n      \\\"type\\\": \\\"integer\\\",\\n      \\\"value\\\": \\\"18\\\",\\n      \\\"required\\\": true,\\n      \\\"label\\\": \\\"Outer padding (px)\\\",\\n      \\\"showIf\\\": [\\n        {\\n          \\\"field\\\": \\\"theme\\\",\\n          \\\"operator\\\": \\\"eq\\\",\\n          \\\"value\\\": \\\"custom\\\"\\n        }\\n      ]\\n    },\\n    {\\n      \\\"name\\\": \\\"showMonthYear\\\",\\n      \\\"type\\\": \\\"boolean\\\",\\n      \\\"value\\\": \\\"true\\\",\\n      \\\"required\\\": true,\\n      \\\"label\\\": \\\"Show month & year title\\\",\\n      \\\"showIf\\\": [\\n        {\\n          \\\"field\\\": \\\"theme\\\",\\n          \\\"operator\\\": \\\"eq\\\",\\n          \\\"value\\\": \\\"custom\\\"\\n        }\\n      ]\\n    },\\n    {\\n      \\\"name\\\": \\\"monthYearPosition\\\",\\n      \\\"type\\\": \\\"select\\\",\\n      \\\"options\\\": [\\n        \\\"top\\\",\\n        \\\"bottom\\\",\\n        \\\"none\\\"\\n      ],\\n      \\\"value\\\": \\\"top\\\",\\n      \\\"required\\\": true,\\n      \\\"label\\\": \\\"Title position (ignored if hidden)\\\",\\n      \\\"showIf\\\": [\\n        {\\n          \\\"field\\\": \\\"theme\\\",\\n          \\\"operator\\\": \\\"eq\\\",\\n          \\\"value\\\": \\\"custom\\\"\\n        }\\n      ]\\n    },\\n    {\\n      \\\"name\\\": \\\"showGrid\\\",\\n      \\\"type\\\": \\\"boolean\\\",\\n      \\\"value\\\": \\\"true\\\",\\n      \\\"required\\\": true,\\n      \\\"label\\\": \\\"Show grid lines\\\",\\n      \\\"showIf\\\": [\\n        {\\n          \\\"field\\\": \\\"theme\\\",\\n          \\\"operator\\\": \\\"eq\\\",\\n          \\\"value\\\": \\\"custom\\\"\\n        }\\n      ]\\n    },\\n    {\\n      \\\"name\\\": \\\"gridWidth\\\",\\n      \\\"type\\\": \\\"float\\\",\\n      \\\"value\\\": \\\"1\\\",\\n      \\\"required\\\": true,\\n      \\